package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Locale;

/** Converts significant canonical history into inheritable consequences for future campaigns sharing a world seed. */
public final class CampaignLegacyEngine {
    private final AppDb db;private final WorldHistoryEngine history;
    public CampaignLegacyEngine(AppDb database){db=database;history=new WorldHistoryEngine(database);AppDb.ensureSixZeroSchema(db.getWritableDatabase());}
    public synchronized JSONObject crystallize(){JSONObject out=new JSONObject();int added=0;try{history.ingestCanonicalFacts();JSONObject seed=history.worldSeed();String seedId=seed.optString("seed_id");if(seedId.isEmpty())seedId=history.ensureSeed(db.getCampaign().optString("name")+" — mundo persistente");int generation=Math.max(1,seed.optInt("generation",1));String campaign=db.getCampaign().optString("name");JSONArray important=history.important(120);for(int i=0;i<important.length();i++){JSONObject e=important.optJSONObject(i);if(e==null||e.optInt("significance",0)<60)continue;String key="history:"+e.optString("event_key");if(db.queryOne("SELECT id FROM campaign_legacies WHERE world_profile=? AND world_seed=? AND legacy_key=?",new String[]{db.getActiveMapProfile(),seedId,key}).length()>0)continue;ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("world_seed",seedId);v.put("legacy_key",key);v.put("source_campaign",campaign);v.put("generation",generation);v.put("category",category(e));v.put("subject",e.optString("title"));v.put("statement",e.optString("summary"));v.put("location",e.optString("location"));v.put("inheritable",1);v.put("active",1);v.put("evidence_json",new JSONArray().put(e.optString("event_key")).toString());v.put("created_day",e.optInt("day_number",1));v.put("created_at",System.currentTimeMillis());if(db.getWritableDatabase().insertWithOnConflict("campaign_legacies",null,v,SQLiteDatabase.CONFLICT_IGNORE)>0)added++;}out.put("added",added).put("seed",seedId).put("legacies",list(80));}catch(Exception e){try{out.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("CampaignLegacyEngine","Falha tolerada na camada 6.0.",ignored);}}return out;}
    public JSONArray list(int limit){JSONObject seed=history.worldSeed();return new JSONArray(db.queryList("SELECT * FROM campaign_legacies WHERE world_profile=? AND world_seed=? AND active=1 ORDER BY generation,created_day,id LIMIT "+Math.max(1,Math.min(500,limit)),new String[]{db.getActiveMapProfile(),seed.optString("seed_id")}));}
    public synchronized JSONObject beginNextGeneration(String campaignName,String eraLabel){JSONObject out=new JSONObject();try{crystallize();JSONObject seed=history.worldSeed();int next=Math.max(1,seed.optInt("generation",1))+1;ContentValues v=new ContentValues();v.put("generation",next);v.put("origin_campaign",campaignName==null?db.getCampaign().optString("name"):campaignName);v.put("era_label",eraLabel==null||eraLabel.trim().isEmpty()?"Nova era":eraLabel.trim());v.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().update("world_seeds",v,"world_profile=?",new String[]{db.getActiveMapProfile()});out.put("generation",next).put("seed_id",seed.optString("seed_id")).put("inherited",list(200));}catch(Exception e){try{out.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("CampaignLegacyEngine","Falha tolerada na camada 6.0.",ignored);}}return out;}
    public synchronized JSONObject beginLegacyCampaign(final String newName,final String eraLabel,final int yearsLater){
        final JSONObject out=new JSONObject();try{
            crystallize();final JSONObject oldCampaign=new JSONObject(db.getCampaign().toString());final int oldDay=Math.max(1,db.getSceneState().optInt("day_number",1));final int daysPerYear=Math.max(1,db.queryOne("SELECT days_per_year FROM living_world_state WHERE world_profile=?",new String[]{db.getActiveMapProfile()}).optInt("days_per_year",365));final int newDay=oldDay+Math.max(0,yearsLater)*daysPerYear;
            db.runInTransactionChecked(new AppDb.CheckedTransaction(){public void run()throws Exception{
                beginNextGeneration(oldCampaign.optString("name"),eraLabel);
                String name=newName==null||newName.trim().isEmpty()?"Nova campanha no mesmo mundo":newName.trim();db.saveCampaign(name,oldCampaign.optString("rules_profile"),oldCampaign.optString("tone"),oldCampaign.optInt("feats",1)==1,oldCampaign.optInt("multiclass",1)==1,oldCampaign.optInt("flanking",0)==1,"Continuidade do world seed; geração sucessora. "+oldCampaign.optString("notes"));
                android.content.ContentValues hv=new android.content.ContentValues();hv.put("active",0);hv.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().update("characters",hv,"world_profile=?",new String[]{db.getActiveMapProfile()});
                db.getWritableDatabase().delete("combatants","world_profile=?",new String[]{db.getActiveMapProfile()});db.getWritableDatabase().delete("tactical_tokens","world_profile=?",new String[]{db.getActiveMapProfile()});
                JSONObject scene=db.getSceneState();scene.put("day_number",newDay).put("clock_hour",9).put("present_npcs_json","[]").put("threats_json","[]").put("clues_json","[]").put("pending_consequences_json","[]");db.saveSceneState(scene);db.saveStoryState(false,"","","[]","","");
                android.content.ContentValues cs=new android.content.ContentValues();cs.put("round_no",1);cs.put("turn_index",0);cs.put("running",0);cs.put("state","idle");cs.put("pending_roll_json","{}");cs.put("encounter_id","");cs.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().update("combat_state_profiles",cs,"world_profile=?",new String[]{db.getActiveMapProfile()});
                db.addJournalFact("Uma nova era começa",name+" começa "+Math.max(0,yearsLater)+" ano(s) após a campanha anterior. O mundo preserva suas consequências canônicas.","Legado","legacy-generation-"+System.currentTimeMillis(),"legacy");
            }});
            new LivingSettlementEngine(db).simulateToDay(newDay);new RumorNetworkEngine(db).update(newDay);out.put("ok",true).put("day",newDay).put("generation",history.worldSeed().optInt("generation",1)).put("seed",history.worldSeed());
        }catch(Exception e){try{out.put("ok",false).put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("CampaignLegacyEngine","Falha tolerada na camada 6.0.",ignored);}}return out;
    }

    public JSONObject context(){JSONObject o=new JSONObject();try{o.put("world_seed",history.worldSeed()).put("active_legacies",list(40)).put("contract","Legado nasce de história canônica e pode influenciar novas campanhas; não altera regras ou fichas sem resolução própria.");}catch(Exception ignored){AppLog.ignored("CampaignLegacyEngine","Falha tolerada na camada 6.0.",ignored);}return o;}
    private static String category(JSONObject e){String s=(e.optString("title")+" "+e.optString("summary")+" "+e.optString("tags_json")).toLowerCase(Locale.ROOT);if(s.matches(".*(fundad|cidade|fortaleza|base|sede).*"))return "place";if(s.matches(".*(morte|herói|heroi|npc|rei|rainha).*"))return "person";if(s.matches(".*(guilda|facção|faccao|aliança|alianca).*"))return "organization";if(s.matches(".*(artefato|espada|relíquia|reliquia).*"))return "relic";return "memory";}
}
